static int abs_int(int x) { return x < 0 ? -x : x; }

int main(void) {
    int N, A, B;
    if (scanf("%d %d %d", &N, &A, &B) != 3) return 0;

    int *da = (int*)malloc((N + 1) * sizeof(int));
    int *db = (int*)malloc((N + 1) * sizeof(int));
    if (!da || !db) return 0;

    for (int i = 1; i <= N; i++) scanf("%d", &da[i]);
    for (int i = 1; i <= N; i++) scanf("%d", &db[i]);

    int D = da[B];

    /* Basic consistency checks */
    if (A < 1 || A > N || B < 1 || B > N) {
        printf("-1\n");
        free(da); free(db);
        return 0;
    }
    if (da[A] != 0 || db[B] != 0 || db[A] != D || D != da[B]) {
        printf("-1\n");
        free(da); free(db);
        return 0;
    }

    /* Count vertices in each layer from A and on each shortest-path position */
    long long *cntA = (long long*)calloc(D + 1, sizeof(long long));
    long long *mid = (long long*)calloc(D + 1, sizeof(long long));
    if (!cntA || !mid) {
        free(da); free(db); free(cntA); free(mid);
        return 0;
    }

    for (int v = 1; v <= N; v++) {
        int x = da[v], y = db[v];

        if (x < 0 || y < 0) {
            printf("-1\n");
            free(da); free(db); free(cntA); free(mid);
            return 0;
        }

        /* Necessary metric conditions */
        if (x + y < D || abs_int(x - y) > D) {
            printf("-1\n");
            free(da); free(db); free(cntA); free(mid);
            return 0;
        }

        if (x <= D) cntA[x]++;

        /* Vertex lies on some shortest A-B path iff x + y == D */
        if (x + y == D) {
            if (x < 0 || x > D) {
                printf("-1\n");
                free(da); free(db); free(cntA); free(mid);
                return 0;
            }
            mid[x]++;
        }
    }

    /* On every position of a shortest A-B path, exactly one vertex is possible
       in a graph realizing all distances with minimum edges.
       In fact, existence already requires exactly one such vertex at each layer:
       otherwise two different vertices would both have x+y=D and same x, forcing
       impossible equal distances to both A and B on the unique metric backbone. */
    for (int i = 0; i <= D; i++) {
        if (mid[i] != 1) {
            printf("-1\n");
            free(da); free(db); free(cntA); free(mid);
            return 0;
        }
    }

    /* For every non-backbone vertex v with distance x from A, to keep graph connected
       and preserve distances, it can be attached by one edge to some vertex in layer x-1.
       This is possible iff layer x-1 is non-empty. Since backbone provides one vertex
       in each layer 0..D, this always holds for x>=1.
       Minimum edges = (backbone path D edges) + one edge per extra vertex = N-1. */
    printf("%d\n", N - 1);

    free(da);
    free(db);
    free(cntA);
    free(mid);
    return 0;
}

