int main(){
    int n;
    cin >> n;
    vector<int> ds(n), dt(n);
    for(int i=0;i<n;i++) cin >> ds[i];
    for(int i=0;i<n;i++) cin >> dt[i];

    // Validity checks
    // ds[0]=0, dt[1]=0 (assuming s=0, t=1)
    int dst = ds[1]; // distance from s to t
    if(dt[0] != dst){ cout << -1; return 0; }

    for(int v=0;v<n;v++){
        if(ds[v]+dt[v] < dst || abs(ds[v]-dt[v]) > dst){
            cout << -1; return 0;
        }
        // parity check
        if((ds[v]+dt[v]-dst)%2 != 0){ cout << -1; return 0; }
    }

    // Count minimum edges
    // For each vertex v != s, need parent in s-tree
    // For each vertex v != t, need parent in t-tree
    // Check if we can share

    long long edges = 0;
    for(int v=0;v<n;v++){
        if(ds[v]==0 && dt[v]==0){ continue; } // both sources same vertex
        bool need_s = (ds[v] > 0);
        bool need_t = (dt[v] > 0);
        if(!need_s && !need_t) continue;
        if(need_s && need_t){
            // Can we share? Need u with ds[u]=ds[v]-1, dt[u]=dt[v]-1
            // Such u exists if ds[v]-1+dt[v]-1 >= dst and parity ok and |..| <= dst
            int a = ds[v]-1, b = dt[v]-1;
            if(a+b >= dst && abs(a-b) <= dst && (a+b-dst)%2==0){
                edges++; // shared edge
            } else {
                edges += 2;
            }
        } else {
            edges++;
        }
    }

    cout << edges;
    return 0;
}

