int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<int> d1(N + 1), d2(N + 1);
    for (int i = 1; i <= N; ++i) cin >> d1[i];
    for (int i = 1; i <= N; ++i) cin >> d2[i];

    const int INF = 1e9;

    // Vertex 1 and vertex 2 are the two specific vertices.
    // Hence:
    // dist(1,1)=0, dist(2,2)=0, dist(1,2)=dist(2,1)=D
    if (d1[1] != 0 || d2[2] != 0) {
        cout << -1 << '\n';
        return 0;
    }

    int D = d2[1];
    if (d1[2] != D || D <= 0) {
        cout << -1 << '\n';
        return 0;
    }

    // Necessary condition for every vertex:
    // |d1-d2| <= D <= d1+d2
    for (int i = 1; i <= N; ++i) {
        if (abs(d1[i] - d2[i]) > D || D > d1[i] + d2[i]) {
            cout << -1 << '\n';
            return 0;
        }
    }

    // For each vertex define:
    // x = (d1 - d2 + D)/2   position on the shortest path 1..2
    // y = (d1 + d2 - D)/2   distance from that path
    // Need integrality.
    vector<vector<int>> groups(D + 1); // groups[x] contains y values for vertices at position x
    for (int i = 1; i <= N; ++i) {
        int a = d1[i] - d2[i] + D;
        int b = d1[i] + d2[i] - D;
        if (a < 0 || b < 0 || (a & 1) || (b & 1)) {
            cout << -1 << '\n';
            return 0;
        }
        int x = a / 2;
        int y = b / 2;
        if (x < 0 || x > D) {
            cout << -1 << '\n';
            return 0;
        }
        groups[x].push_back(y);
    }

    long long edges = D; // backbone shortest path from 1 to 2

    for (int x = 0; x <= D; ++x) {
        auto &v = groups[x];
        sort(v.begin(), v.end());

        // Need exactly one vertex with y=0 for each x on backbone.
        if (v.empty() || v[0] != 0) {
            cout << -1 << '\n';
            return 0;
        }
        int cnt0 = 0;
        while (cnt0 < (int)v.size() && v[cnt0] == 0) cnt0++;
        if (cnt0 != 1) {
            cout << -1 << '\n';
            return 0;
        }

        // For y>0, to minimize edges, each level y must have at least one parent at y-1.
        // Therefore all positive y values in this group must form a contiguous set 1..maxY.
        int expected = 1;
        for (int i = cnt0; i < (int)v.size(); ) {
            int y = v[i];
            if (y != expected) {
                cout << -1 << '\n';
                return 0;
            }
            int j = i;
            while (j < (int)v.size() && v[j] == y) j++;
            edges += (j - i); // each such vertex needs one edge to previous level
            expected++;
            i = j;
        }
    }

    cout << edges << '\n';
    return 0;
}
